#!/usr/bin/env node
/**
 * Acceptance-check — Report Renderer
 *
 * Combines .github/.pipeline-context/verify/<id>.acceptance.facts.json (script) with
 * .github/.pipeline-context/verify/<id>.acceptance.verdict.json (agent) into
 * docs/agent_output/04-verify/acceptance_<id>.md.
 *
 * Usage:
 *   node scripts/render-acceptance.js --all
 *   node scripts/render-acceptance.js --story JIRA-001
 */
const fs = require('fs');
const path = require('path');
const {
  rel, listStep1Changes, factsPathFor, verdictPathFor, reportPathFor, rewriteVerifyIndex,
} = require('./lib/verify');

const VERDICTS = ['SATISFIED', 'NOT_SATISFIED', 'INCONCLUSIVE'];
const REQUIRED = [
  ['verdict', (v) => VERDICTS.includes(v.verdict)],
  ['plain_summary', (v) => typeof v.plain_summary === 'string' && v.plain_summary.trim()],
  ['criteria_results', (v) => Array.isArray(v.criteria_results) && v.criteria_results.length],
  ['reasoning', (v) => typeof v.reasoning === 'string' && v.reasoning.trim()],
];

function validate(v) {
  const missing = REQUIRED.filter(([, check]) => !check(v)).map(([k]) => k);
  if (missing.length) throw new Error(`acceptance verdict is missing required field(s): ${missing.join(', ')}. See templates/acceptance.schema.json.`);
}

function render(facts, verdict) {
  const out = [];
  out.push(`# Acceptance-check — ${facts.id}`);
  out.push('');
  out.push(`## ${facts.title}`);
  out.push('');
  out.push(`> ${verdict.plain_summary.trim()}`);
  out.push('');
  out.push(`_Generated by the existing-app test agent on ${new Date().toISOString().slice(0, 10)}. Facts collected ${facts.generatedAt}._`);
  out.push('');

  const met = verdict.criteria_results.filter((c) => c.met).length;
  out.push('## At a glance');
  out.push('');
  out.push('| | |', '|---|---|');
  out.push(`| **Verdict** | ${verdict.verdict} |`);
  out.push(`| **Confidence** | ${verdict.confidence || 'not stated'} |`);
  out.push(`| **Criteria met** | ${met} of ${verdict.criteria_results.length} |`);
  out.push('');

  out.push('## 1. Criteria checked against the patched code', '');
  out.push('| # | Criterion | Met | Reasoning |', '|---|---|---|---|');
  verdict.criteria_results.forEach((c, i) => out.push(`| ${i + 1} | ${c.criterion} | ${c.met ? '✅' : '❌'} | ${c.reasoning || ''} |`));
  out.push('');

  out.push('## 2. Reasoning', '', verdict.reasoning.trim(), '');

  if (verdict.open_questions && verdict.open_questions.length) {
    out.push('## Open questions', '');
    verdict.open_questions.forEach((q) => out.push(`- ${q}`));
    out.push('');
  }

  out.push('---', '', `Source development report: \`${facts.sources.devReport}\`.`, '');
  return out.join('\n');
}

function parseArgs(argv) {
  const args = {};
  for (let i = 0; i < argv.length; i += 1) {
    const a = argv[i];
    if (a === '--story' || a === '-s') args.story = argv[++i];
    else if (a === '--all' || a === '-a') args.all = true;
  }
  return args;
}

function renderOne(id) {
  const ff = factsPathFor(id, 'acceptance');
  if (!fs.existsSync(ff)) throw new Error(`No facts at ${rel(ff)}. Run collect-acceptance.js --story ${id} first.`);
  const facts = JSON.parse(fs.readFileSync(ff, 'utf8'));

  const vf = verdictPathFor(id, 'acceptance');
  if (!fs.existsSync(vf)) throw new Error(`No verdict at ${rel(vf)}. Read the briefing and write it, per templates/acceptance.schema.json.`);
  const verdict = JSON.parse(fs.readFileSync(vf, 'utf8'));
  validate(verdict);

  const target = reportPathFor(id, 'acceptance');
  fs.mkdirSync(path.dirname(target), { recursive: true });
  fs.writeFileSync(target, render(facts, verdict));
  return { id, verdict: verdict.verdict, report: rel(target) };
}

function main() {
  const args = parseArgs(process.argv.slice(2));
  if (args.all) {
    const targets = listStep1Changes();
    const written = []; const skipped = [];
    for (const t of targets) {
      try { const r = renderOne(t.id); written.push(r); console.log(`${r.id.padEnd(10)} ${r.verdict.padEnd(15)} -> ${r.report}`); } catch (err) { skipped.push(t.id); console.error(`${t.id.padEnd(10)} SKIPPED  ${err.message.split('\n')[0]}`); }
    }
    rewriteVerifyIndex();
    console.log(`\nWrote ${written.length}/${targets.length} report(s).`);
    if (skipped.length) process.exitCode = 1;
    return;
  }
  if (!args.story) throw new Error('Missing --story or --all.');
  const r = renderOne(args.story);
  rewriteVerifyIndex();
  console.log(`Acceptance-check — wrote ${r.report} (${r.verdict})`);
}

try {
  main();
} catch (err) {
  console.error('Rendering failed:', err.message);
  process.exit(1);
}
